def shared_PV(controller, references, device, run_id):
 import sys,time,collections
 sys.path.insert(0,'results/T-048/scripts')
 from chay import OUT,read,dump,sha
 from kiem import read_run
 from cham import WORLDS
 folder=OUT/'runs'/run_id;folder.mkdir();start=time.monotonic();refs={};hashes={};allocation=read(OUT/'ma-tran.json')['allocation'];totals=collections.Counter()
 for name in [*references,controller]:
  assert read(OUT/'runs'/name/'kiem.json')['success']
  for child in read(OUT/'runs'/name/'kiem.json')['finished']:
   cmd,meta,pairs=read_run(OUT/'runs'/child);hashes[child]=meta
   if name in references:
    for job in cmd['plan']['jobs']:
     if allocation[job['opaque_id']]==device:refs[(job['opaque_id'],job['window'])]=child
 (folder/'command.json').write_text(dump(dict(controller=controller,references=references,device=device,phase1=hashes,analysis_source=ANALYSIS_SOURCE,no_labels=True))+'\n',encoding='utf-8')
 with (folder/'trung-gian.jsonl').open('x',encoding='utf-8') as output:
  for child in read(OUT/'runs'/controller/'kiem.json')['finished']:
   cmd,_,pairs=read_run(OUT/'runs'/child);job=cmd['plan']['jobs'][0];_,_,rp=read_run(OUT/'runs'/refs[(job['opaque_id'],job['window'])]);r0,d0=next(rp());batch={r['config_id']:(r,d) for r,d in pairs()};batch[r0['config_id']]=(r0,d0)
   for base,eid in (('R0','R0-E4-S1-e0.05-a0.01'),('E1+E2','E1+E2-E4-S1')):
    e=batch[eid][1]['trace'];z=batch[base+'-z-S1'][1]['trace'];z0=batch[base+'-z-S0'][1]['trace'];pvs=[t['phan_vi'] for t in (e,z,z0)];assert all(p.keys()==pvs[0].keys() for p in pvs)
    finite=oldmissing=0
    for u in pvs[0]:
     assert pvs[0][u]['mau_sha256']==pvs[1][u]['mau_sha256']==pvs[2][u]['mau_sha256']
     assert pvs[0][u]['e4']==pvs[1][u]['e4']==pvs[2][u]['e4']
     assert pvs[1][u].get('z')==pvs[2][u].get('z')
     if 'z' in pvs[1][u]:
      assert pvs[1][u]['oracle']['z']==pvs[2][u]['oracle']['z']=='finite_formula_match';finite+=1;oldmissing+='oracle' not in pvs[0][u]
    for i,w in enumerate(WORLDS):
     assert z['xep'][i]['kenh']==z0['xep'][i]['kenh']
     assert e['xep'][i]['m']==z['xep'][i]['m'] and e['don_vi_the_gioi'][i]['m']==z['don_vi_the_gioi'][i]['m']
    row=dict(opaque_id=job['opaque_id'],window=job['window'],base=base,source_child=child,PV_units=len(pvs[0]),finite_oracle_units=finite,old_reference_missing_oracle=oldmissing,samples_and_pre_E4_exact=True,zS1_zS0_channels_exact=True,E4_z_m_exact=True)
    output.write(dump(row)+'\n');totals.update(base_windows=1,PV_units=len(pvs[0]),finite_oracle_units=finite,old_reference_missing_oracle=oldmissing)
 (folder/'kiem.json').write_text(dump(dict(closed=True,totals=totals,trace_sha256=sha(folder/'trung-gian.jsonl'),wall_seconds=time.monotonic()-start))+'\n',encoding='utf-8')
 return dict(totals)
